const label=(x,y,t,small=false)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${small?17:23}" fill="var(--ink)">${t}</text>`;
export function renderGrounding(compact=false) {
 const body=`<circle cx="100" cy="215" r="47" fill="var(--surface)" stroke="var(--line)" stroke-width="2"/><path d="M72 215q14-34 28 0t28 0" fill="none" stroke="var(--green)" stroke-width="3"/><rect x="630" y="110" width="280" height="265" rx="12" fill="var(--panel)" stroke="var(--line)" stroke-width="3"/><path d="M100 168V55H310M380 55H765V170" stroke="var(--gold)" stroke-width="5" fill="none"/><path d="M310 55H380" stroke="var(--gold)" stroke-width="7"/><circle cx="310" cy="55" r="5" fill="var(--ink)"/><circle cx="380" cy="55" r="5" fill="var(--ink)"/><path d="M753 173l24 20-28 19 18 20" fill="none" stroke="var(--red)" stroke-width="7"/><circle cx="766" cy="240" r="6" fill="var(--green)"/><path d="M766 240V335H100V262" fill="none" stroke="var(--green)" stroke-width="5"/><path d="M105 335v65m-20 0h40m-34 9h28m-21 9h14" fill="none" stroke="var(--muted)" stroke-width="2"/>${label(100,300,'Source',true)}${label(345,29,'Breaker',true)}${label(540,32,'Live conductor',true)}${label(773,285,'Metal cabinet')}${label(775,90,'Insulation fault',true)}${label(428,310,'PE: protective earth conductor',true)}${label(100,452,'Source earth',true)}<path d="M570 335l18-9v18zM530 55l-18-9v18z" fill="var(--green)"/>`;
 const small=`<circle cx="48" cy="180" r="27" fill="var(--panel)"/><path d="M30 180q9-22 18 0t18 0" fill="none" stroke="var(--green)" stroke-width="3"/><rect x="229" y="150" width="128" height="172" rx="9" fill="var(--panel)" stroke="var(--line)"/><path d="M48 153V62H289V177" stroke="var(--gold)" stroke-width="4" fill="none"/><path d="M280 177l17 17-17 16 10 14" stroke="var(--red)" stroke-width="5" fill="none"/><path d="M290 225V292H48V207" stroke="var(--green)" stroke-width="4" fill="none"/><path d="M110 62h50" stroke="var(--ink)" stroke-width="7"/><path d="M48 292v52m-14 0h28m-23 7h18m-14 7h10" stroke="var(--muted)" fill="none"/>${label(134,39,'Breaker',true)}${label(293,135,'Fault',true)}${label(291,260,'Metal case',true)}${label(127,265,'PE return',true)}${label(196,89,'Live conductor',true)}${label(53,390,'Source earth',true)}`;
 return `<div class="bonding-view"><svg viewBox="${compact?'0 0 380 420':'0 0 1000 470'}" role="img" aria-label="A live conductor touches a metal cabinet. Its protective earth conductor returns fault current to the source so the breaker can disconnect the faulty circuit.">${compact?small:body}</svg><div class="bonding-definitions"><p><strong>Bond the metal case</strong>A protective conductor connects it back to the source.</p><p><strong>Complete the fault loop</strong>Fault current makes the protection disconnect the circuit.</p></div></div>`;
}
function contact(stage) {
 const opened=stage!=='closed',arc=stage==='arc',extinguished=stage==='cleared';
 return `<article class="arc-case"><svg viewBox="0 0 520 330" role="img" aria-label="Contacts ${opened?'open':'closed'}${arc?', current still flows through an arc':extinguished?', current has been interrupted':''}."><rect x="12" y="108" width="120" height="96" rx="8" fill="var(--panel)"/><rect x="390" y="108" width="118" height="96" rx="8" fill="var(--panel)"/>${label(72,163,'Source')}${label(449,163,'Load')}<path d="M132 155h85M303 155h87M449 204v70H72v-70" fill="none" stroke="${extinguished?'var(--line)':'var(--green)'}" stroke-width="4"/><circle cx="217" cy="155" r="7" fill="var(--ink)"/><circle cx="303" cy="155" r="7" fill="var(--ink)"/><path d="M217 155L${opened?'273 95':'303 155'}" fill="none" stroke="var(--ink)" stroke-width="7" stroke-linecap="round"/>${arc?'<path d="M277 100l-5 20 15-6-2 20 13 9" fill="none" stroke="var(--gold)" stroke-width="6"/>':''}${label(260,50,opened?'Contacts separated':'Contacts touching',true)}${arc?label(260,222,'Arc carries current',true):extinguished?label(260,222,'Current = 0',true):''}</svg><p>${stage==='closed'?'Current flows through the contacts.':stage==='arc'?'Separated contacts can still conduct through an arc.':'The arc is extinguished; the open gap withstands the voltage.'}</p></article>`;
}
export function renderInterruption(stage='arc') {
 return `<div class="arc-sequence">${contact(stage)}</div>`;
}
export function renderDCProtection(compact=false) {
 if(compact) return `<div class="dc-protection"><svg viewBox="0 0 380 620" role="img" aria-label="800 volt rectifier and bus capacitor feed a cable and DC breaker before the rack feeder fault."><rect x="110" y="15" width="180" height="75" rx="9" fill="var(--panel)"/>${label(200,45,'Rectifier')}${label(200,75,'800 V DC',true)}<path d="M290 52h50v90m0 0c-35 0-35 22 0 22c-35 0-35 22 0 22c-35 0-35 22 0 22v53m0 76v178h-50M110 52H40v463h70M40 112h135m25 0h140" fill="none" stroke="var(--green)" stroke-width="4"/><path d="M176 94v36m23-36v36" stroke="var(--green)" stroke-width="5"/>${label(182,161,'Bus capacitor',true)}${label(193,219,'Cable inductance',true)}<rect x="240" y="261" width="134" height="76" rx="10" fill="var(--surface)" stroke="var(--gold)" stroke-width="3"/>${label(307,292,'DC breaker',true)}${label(307,321,'Arc chamber',true)}<path d="M340 397H225l-15-13-15 26-15-13H40" stroke="var(--red)" stroke-width="4" fill="none"/>${label(192,438,'Feeder short circuit',true)}<rect x="110" y="478" width="180" height="75" rx="9" fill="var(--panel)"/>${label(200,509,'Rack')}${label(200,538,'converters',true)}</svg><div class="dc-protection-facts"><span><strong>DC voltage rating</strong>Withstand the open-circuit voltage</span><span><strong>Interrupting rating</strong>Clear the available fault current</span><span><strong>Stored energy</strong>Handle energy released during clearing</span></div></div>`;

 return `<div class="dc-protection"><svg viewBox="0 0 1100 400" role="img" aria-label="An 800 volt rectifier and charged bus capacitor feed a branch. Cable inductance stores magnetic energy. The DC breaker must interrupt current and manage that stored energy."><rect x="20" y="90" width="170" height="145" rx="12" fill="var(--panel)"/><rect x="880" y="90" width="185" height="145" rx="12" fill="var(--panel)"/>${label(105,145,'Rectifier')}${label(105,179,'800 V DC')}${label(972,150,'Rack')}${label(972,183,'converters',true)}<path d="M190 125H360m0 0c0-45 25-45 25 0c0-45 25-45 25 0c0-45 25-45 25 0c0-45 25-45 25 0H580M740 125H880M972 235v100H105V235M275 125v78M275 230v105" stroke="var(--green)" stroke-width="5" fill="none"/><path d="M250 204h50M250 228h50" stroke="var(--green)" stroke-width="6"/><path d="M818 125v78l-13 14 26 15-26 15 13 14v74" stroke="var(--red)" stroke-width="4" fill="none"/>${label(827,290,'Short circuit',true)}<rect x="580" y="78" width="160" height="100" rx="10" fill="var(--surface)" stroke="var(--gold)" stroke-width="3"/>${label(660,120,'DC breaker')}${label(660,150,'+ arc chamber',true)}${label(414,60,'Cable inductance',true)}${label(277,280,'Capacitor',true)}${label(659,218,'Lengthen and cool the arc',true)}${label(659,249,'until current reaches zero',true)}</svg><div class="dc-protection-facts"><span><strong>DC voltage rating</strong>Withstand the open-circuit voltage</span><span><strong>Interrupting rating</strong>Clear the available fault current</span><span><strong>Stored energy</strong>Handle energy released during clearing</span></div></div>`;
}
